contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 itemPrice, uint16 dailyAllowance, uint256 quantity, address receiver) public {
        require(itemPrice > 0 && dailyAllowance > 0);
        require(quantity > 0);
        require(receiver != address(0));

        c.createGameItem("testItem", "ipfs://test", false, true, 0, itemPrice, dailyAllowance); if (__ESBMC_reverted()) return;
        c.mint(0, quantity); if (__ESBMC_reverted()) return;

        uint256 balance = c.balanceOf(address(this), 0); if (__ESBMC_reverted()) return;
        assert(balance == quantity);
    }
}

