pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(uint256 itemPrice, uint16 dailyAllowance, uint256 quantity, address receiver) internal {
        vm.assume(itemPrice > 0 && dailyAllowance > 0);
        vm.assume(quantity > 0);
        vm.assume(receiver != address(0));
        try c.createGameItem("testItem", "ipfs://test", false, true, 0, itemPrice, dailyAllowance) {} catch { return; }
        try c.mint(0, quantity) {} catch { return; }
        uint256 balance;
        try c.balanceOf(address(this), 0) returns (uint256 __r) { balance = __r; } catch { return; }
        assertTrue(balance == quantity);
    }

    function testFuzz_run(uint256 itemPrice, uint16 dailyAllowance, uint256 quantity, address receiver) public {
        vm.assume(receiver.code.length == 0 && uint160(receiver) > 0xffff && receiver != address(this) && receiver != address(c) && receiver != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && receiver != 0x000000000000000000636F6e736F6c652e6c6f67 && receiver != 0x4e59b44847b379578588920cA78FbF26c0B4956C && receiver != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(itemPrice, dailyAllowance, quantity, receiver);
    }

    receive() external payable {}
}
